// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CartoonGraphProps = Record<string, any>;

const CartoonGraph: React.FC<CartoonGraphProps> = ({
  backgroundColor = "#fffbeb", // Creamy background
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "Growth Chart!",
  mainColor = "#ff6b6b", // Pastel Red
  secondaryColor = "#4ecdc4", // Pastel Teal
  axisColor = "#2d3436", // Dark Charcoal
  bar1Value = 40,
  bar2Value = 65,
  bar3Value = 30,
  bar4Value = 85,
  bar5Value = 55,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Fredoka"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Staggered springs for bars
  const springConfig = {
    damping: 12,
    mass: 0.8,
    stiffness: 150,
    overshootClamping: false,
  };

  const barValues = [bar1Value, bar2Value, bar3Value, bar4Value, bar5Value];
  const maxBarValue = 100; // Normalizing based on max schema value

  // Entrance animations
  const titleSpring = spring({
    frame: frame - 5,
    fps,
    config: { damping: 10, stiffness: 100 },
  });

  const axisProgress = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 80 },
  });

  const axisLength = interpolate(axisProgress, [0, 1], [0, 100]);
  
  // Dimensions
  const graphWidth = width * 0.7;
  const graphHeight = height * 0.5;
  const startX = (width - graphWidth) / 2;
  
  // Centering Logic:
  // Title at 10%, Graph bottom at 85%.
  // Graph occupies 35% -> 85% of height (50% height).
  // Title occupies ~10% -> ~20% of height.
  // Gap is ~15%.
  const startY = height * 0.85; 

  const barWidth = graphWidth / (barValues.length * 1.5);
  const spacing = (graphWidth - (barWidth * barValues.length)) / (barValues.length + 1);

  // Styling constants
  const borderThickness = Math.max(3, width * 0.005);
  const borderRadius = width * 0.015;
  
  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Fredoka", alignItems: 'center', justifyContent: 'center' }}>
      
      {/* Title */}
      <div style={{
        position: 'absolute',
        top: height * 0.10, // Adjusted for more separation (higher up)
        width: '100%',
        textAlign: 'center',
        fontSize: width * 0.08,
        fontWeight: 700,
        color: axisColor,
        transform: `scale(${titleSpring})`,
        opacity: interpolate(titleSpring, [0, 0.5], [0, 1]),
      }}>
        {titleText}
      </div>

      {/* Graph Container */}
      <div style={{
        position: 'relative',
        width: width,
        height: height,
      }}>
        
        {/* Y Axis */}
        <div style={{
          position: 'absolute',
          left: startX,
          bottom: height - startY,
          width: borderThickness,
          height: `${axisLength}%`,
          maxHeight: graphHeight,
          backgroundColor: axisColor,
          borderRadius: borderThickness,
          transformOrigin: 'bottom',
        }} />

        {/* X Axis */}
        <div style={{
          position: 'absolute',
          left: startX,
          bottom: height - startY,
          width: `${axisLength}%`,
          maxWidth: graphWidth,
          height: borderThickness,
          backgroundColor: axisColor,
          borderRadius: borderThickness,
          transformOrigin: 'left',
        }} />

        {/* Bars */}
        {barValues.map((val, i) => {
          const delay = i * 5 + 10;
          
          const barSpring = spring({
            frame: frame - delay,
            fps,
            config: springConfig
          });

          // Calculate current height based on spring and value
          const targetHeight = (val / maxBarValue) * graphHeight;
          const currentHeight = interpolate(barSpring, [0, 1], [0, targetHeight]);

          // Alternate colors
          const barColor = i % 2 === 0 ? mainColor : secondaryColor;

          const leftPos = startX + spacing + (i * (barWidth + spacing));

          return (
            <React.Fragment key={i}>
              {/* Bar Main */}
              <div style={{
                position: 'absolute',
                left: leftPos,
                bottom: height - startY,
                width: barWidth,
                height: Math.max(0, currentHeight),
                backgroundColor: barColor,
                border: `${borderThickness}px solid ${axisColor}`,
                borderBottom: 'none',
                borderTopLeftRadius: borderRadius,
                borderTopRightRadius: borderRadius,
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'center',
                overflow: 'hidden'
              }}>
                 {/* Shine effect */}
                 <div style={{
                    width: '30%',
                    height: '100%',
                    backgroundColor: 'rgba(255,255,255,0.3)',
                    position: 'absolute',
                    left: 0,
                    top: 0
                 }}/>
              </div>
            </React.Fragment>
          );
        })}

      </div>
    </AbsoluteFill>
  );
};

export default CartoonGraph;